import { Column, CreateDateColumn, Entity, Index, JoinColumn, ManyToOne, OneToMany, PrimaryGeneratedColumn, UpdateDateColumn } from 'typeorm';
import { TelegramUser } from './telegram-user.entity';
import { Message } from './message.entity';
import { TicketDepartment, TicketStatus } from '../enums';

@Entity('tickets')
export class Ticket {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * Human-readable number (TKT-10001…) generated by the DB from ticket_number_seq.
   * Never MAX()+1 — the sequence is race-free under concurrency.
   * The service re-reads the ticket after insert because the value is DB-generated.
   */
  @Index('uq_tickets_ticket_number', { unique: true })
  @Column({ type: 'varchar', length: 32 })
  ticket_number: string;

  @Index('idx_tickets_user_id')
  @Column({ type: 'uuid' })
  user_id: string;

  @Column({ type: 'enum', enum: TicketStatus, enumName: 'ticket_status', default: TicketStatus.OPEN })
  status: TicketStatus;

  @Column({ type: 'varchar', length: 120, nullable: true })
  subject: string | null;

  /**
   * Department chosen in the registration wizard (FINANCE/SUPPORT/TECHNICAL/
   * SUGGESTIONS). NULL only for tickets created before this column existed.
   */
  @Column({ type: 'varchar', length: 32, nullable: true })
  department: TicketDepartment | null;

  @CreateDateColumn({ type: 'timestamptz' })
  created_at: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updated_at: Date;

  @Column({ type: 'timestamptz' })
  last_message_at: Date;

  @Column({ type: 'timestamptz', nullable: true })
  closed_at: Date | null;

  @ManyToOne(() => TelegramUser, (u) => u.tickets, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'user_id' })
  user: TelegramUser;

  @OneToMany(() => Message, (m) => m.ticket)
  messages: Message[];
}

/**
 * The critical partial unique index — at most ONE active (non-closed) ticket
 * per user, even under two concurrent /new requests. Defined in the migration:
 *   CREATE UNIQUE INDEX "uq_active_ticket_per_user" ON "tickets" ("user_id")
 *     WHERE "status" <> 'CLOSED';
 */
